import{_ as e,o as a,c as d,a2 as r}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"HTTP Status Codes","description":"","frontmatter":{},"headers":[],"relativePath":"api-documentation/v1/http-status-codes.md","filePath":"api-documentation/v1/http-status-codes.md"}'),o={name:"api-documentation/v1/http-status-codes.md"};function s(n,t,i,l,c,h){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="http-status-codes" tabindex="-1">HTTP Status Codes <a class="header-anchor" href="#http-status-codes" aria-label="Permalink to &quot;HTTP Status Codes&quot;">​</a></h1><p>The status codes contain the following</p><table tabindex="0"><thead><tr><th>Status Code</th><th>Meaning</th></tr></thead><tbody><tr><td>200</td><td>Request was successful</td></tr><tr><td>400</td><td>Bad request. Invalid JSON, schema validation failure, or an invalid request state</td></tr><tr><td>401</td><td>Authorization error. User could not be authenticated</td></tr><tr><td>403</td><td>Permission error. Invalid API key, missing broker session, or blocked by mode/policy</td></tr><tr><td>404</td><td>Broker module, symbol, order, or linked messaging user not found</td></tr><tr><td>409</td><td>Conflict. The server is in the wrong state for the operation (for example, WhatsApp is not paired)</td></tr><tr><td>422</td><td>Request understood but not processable (portfolio analytics with missing or incompatible history)</td></tr><tr><td>429</td><td>Rate limit exceeded. Users have been blocked for exceeding the rate limit.</td></tr><tr><td>500</td><td>Internal server error.</td></tr><tr><td>501</td><td>Not implemented for the connected broker (for example, GTT or margin on a broker without that module)</td></tr></tbody></table><h2 id="schema-validation-returns-400" tabindex="-1">Schema Validation Returns 400 <a class="header-anchor" href="#schema-validation-returns-400" aria-label="Permalink to &quot;Schema Validation Returns 400&quot;">​</a></h2><p>Request bodies are validated by marshmallow schemas that do not allow unknown fields. Sending a field the schema does not declare returns HTTP 400 with the offending key named in <code>message</code>, even when every other field is correct. Use the request-body table on each endpoint page as the exact allowed field set.</p><p>The two exceptions are the GTT place and modify schemas, which silently drop unknown fields, and chart preferences, which is designed to accept arbitrary preference keys.</p>',6)])])}const m=e(o,[["render",s]]);export{p as __pageData,m as default};
